import { describe, expect, it, vi } from "vitest";

import { ScanExecutionError } from "@/server/scans/errors";
import {
  GitHubDesiredStateReader,
  type FetchClient,
} from "@/server/scans/github";

const SHA = "0123456789abcdef0123456789abcdef01234567";

function response(body: unknown, status = 200): Response {
  return Response.json(body, { status });
}

describe("GitHubDesiredStateReader", () => {
  it("resolves a ref then reads exactly one configured file at the SHA", async () => {
    const fetchClient = vi
      .fn<FetchClient>()
      .mockResolvedValueOnce(response({ sha: SHA }))
      .mockResolvedValueOnce(
        response({
          content: Buffer.from("apiVersion: apps/v1").toString("base64"),
          encoding: "base64",
          type: "file",
        }),
      );
    const reader = new GitHubDesiredStateReader(
      "owner/repository",
      "demo/deployment.yaml",
      fetchClient,
    );

    await expect(reader.load("feature/test")).resolves.toEqual({
      resolvedSha: SHA,
      yaml: "apiVersion: apps/v1",
    });
    expect(fetchClient).toHaveBeenCalledTimes(2);
    expect(fetchClient.mock.calls[0]?.[0]).toBe(
      "https://api.github.com/repos/owner/repository/commits/feature%2Ftest",
    );
    expect(fetchClient.mock.calls[1]?.[0]).toBe(
      `https://api.github.com/repos/owner/repository/contents/demo/deployment.yaml?ref=${SHA}`,
    );
    expect(fetchClient.mock.calls[0]?.[1]).toMatchObject({ method: "GET" });
  });

  it.each([
    ["missing ref", [response({}, 404)], "GITHUB_REF_NOT_FOUND"],
    [
      "missing file",
      [response({ sha: SHA }), response({}, 404)],
      "GITHUB_FILE_NOT_FOUND",
    ],
    ["unavailable GitHub", [response({}, 503)], "GITHUB_UNAVAILABLE"],
    [
      "invalid response",
      [response({ sha: "branch-not-sha" })],
      "GITHUB_RESPONSE_INVALID",
    ],
  ])("maps %s without retries", async (_name, responses, code) => {
    const fetchClient = vi.fn<FetchClient>();
    for (const item of responses) {
      fetchClient.mockResolvedValueOnce(item);
    }
    const reader = new GitHubDesiredStateReader(
      "owner/repository",
      "deployment.yaml",
      fetchClient,
    );

    await expect(reader.load("main")).rejects.toEqual(
      expect.objectContaining<Partial<ScanExecutionError>>({ code }),
    );
    expect(fetchClient).toHaveBeenCalledTimes(responses.length);
  });

  it("aborts one hung request at the bounded timeout without retrying", async () => {
    const fetchClient = vi.fn<FetchClient>((_input, init) => {
      return new Promise((_resolve, reject) => {
        init?.signal?.addEventListener("abort", () =>
          reject(new DOMException("aborted", "AbortError")),
        );
      });
    });
    const reader = new GitHubDesiredStateReader(
      "owner/repository",
      "deployment.yaml",
      fetchClient,
      1,
    );

    await expect(reader.load("main")).rejects.toEqual(
      expect.objectContaining<Partial<ScanExecutionError>>({
        code: "GITHUB_TIMEOUT",
      }),
    );
    expect(fetchClient).toHaveBeenCalledOnce();
  });
});

import {
  ApiException,
  HttpMethod,
  RequestContext,
  type V1Deployment,
} from "@kubernetes/client-node";
import { describe, expect, it, vi } from "vitest";

import { ScanExecutionError } from "@/server/scans/errors";
import {
  KubernetesDeploymentReader,
  type AppsV1DeploymentClient,
} from "@/server/scans/kubernetes";

const TARGET = {
  apiVersion: "apps/v1",
  kind: "Deployment",
  name: "app",
  namespace: "demo",
} as const;

function deployment(): V1Deployment {
  return {
    spec: {
      replicas: 2,
      selector: { matchLabels: { app: "demo" } },
      template: {
        metadata: {},
        spec: {
          containers: [
            { image: "worker:1", name: "worker" },
            { image: "api:1", name: "api" },
          ],
        },
      },
    },
  };
}

describe("KubernetesDeploymentReader", () => {
  it("performs one namespaced Deployment read and projects supported fields", async () => {
    const client: AppsV1DeploymentClient = {
      readNamespacedDeployment: vi.fn().mockResolvedValue(deployment()),
    };
    const reader = new KubernetesDeploymentReader(client);

    await expect(reader.read(TARGET)).resolves.toEqual({
      containers: [
        { image: "api:1", name: "api" },
        { image: "worker:1", name: "worker" },
      ],
      replicas: 2,
    });
    expect(client.readNamespacedDeployment).toHaveBeenCalledOnce();
    expect(client.readNamespacedDeployment).toHaveBeenCalledWith(
      { name: "app", namespace: "demo" },
      expect.objectContaining({ middleware: [expect.any(Object)] }),
    );
  });

  it.each([
    [404, null],
    [403, "KUBERNETES_FORBIDDEN"],
    [500, "KUBERNETES_UNAVAILABLE"],
  ])("maps API status %i safely", async (status, expected) => {
    const error = new ApiException(status, "unsafe upstream detail", {}, {});
    const client: AppsV1DeploymentClient = {
      readNamespacedDeployment: vi.fn().mockRejectedValue(error),
    };
    const promise = new KubernetesDeploymentReader(client).read(TARGET);

    if (expected === null) {
      await expect(promise).resolves.toBeNull();
    } else {
      await expect(promise).rejects.toEqual(
        expect.objectContaining<Partial<ScanExecutionError>>({ code: expected }),
      );
    }
    expect(client.readNamespacedDeployment).toHaveBeenCalledOnce();
  });

  it("aborts one hung read at the bounded timeout without retrying", async () => {
    const client: AppsV1DeploymentClient = {
      readNamespacedDeployment: vi.fn(async (_request, options) => {
        const middleware = options?.middleware?.[0];
        const context = new RequestContext(
          "https://cluster.example/apis/apps/v1/namespaces/demo/deployments/app",
          HttpMethod.GET,
        );
        const request = middleware
          ? await middleware.pre(context).toPromise()
          : context;
        return new Promise<V1Deployment>((_resolve, reject) => {
          request
            .getSignal()
            ?.addEventListener("abort", () =>
              reject(new DOMException("aborted", "AbortError")),
            );
        });
      }),
    };

    await expect(
      new KubernetesDeploymentReader(client, 1).read(TARGET),
    ).rejects.toEqual(
      expect.objectContaining<Partial<ScanExecutionError>>({
        code: "KUBERNETES_TIMEOUT",
      }),
    );
    expect(client.readNamespacedDeployment).toHaveBeenCalledOnce();
  });
});

