    rmSync(directory, { force: true, recursive: true });
  }
});

describe("SqliteScanRepository", () => {
  it("bootstraps schema version one idempotently and preserves restart history", () => {
    const path = databasePath();
    const first = new SqliteScanRepository(path);
    first.createQueued("scan-1", "main", "2026-07-31T00:00:00.000Z");
    first.close();

    const second = new SqliteScanRepository(path);
    expect(second.get("scan-1")).toMatchObject({
      id: "scan-1",
      requestedRef: "main",
      stage: "QUEUED",
      status: "QUEUED",
    });
    second.close();

    const inspection = new DatabaseSync(path, { readOnly: true });
    expect(
      inspection.prepare("PRAGMA user_version").get(),
    ).toEqual({ user_version: 1 });
    inspection.close();
  });

  it("binds injection-shaped values and preserves ordered append-only stages", () => {
    const repository = new SqliteScanRepository(":memory:");
    const requestedRef = "main'); DROP TABLE scans; --";
    repository.createQueued(
      "scan-injection",
      requestedRef,
      "2026-07-31T00:00:00.000Z",
    );
    repository.transition(
      "scan-injection",
      "LOADING_DESIRED",
      "RUNNING",
      "2026-07-31T00:00:01.000Z",
    );
    repository.saveDesired(
      "scan-injection",
      "0123456789abcdef0123456789abcdef01234567",
      {
        apiVersion: "apps/v1",
        kind: "Deployment",
        name: "app",
        namespace: "demo",
      },
      { containers: [{ image: "api:1", name: "api" }], replicas: 1 },
      "2026-07-31T00:00:02.000Z",
    );
    repository.saveLive(
      "scan-injection",
      { containers: [{ image: "api:2", name: "api" }], replicas: 2 },
      "2026-07-31T00:00:03.000Z",
    );
    repository.transition(
      "scan-injection",
      "SAVING_RESULT",
      "RUNNING",
      "2026-07-31T00:00:04.000Z",
    );
    repository.complete(
      "scan-injection",
      {
        differences: [
          { desired: 1, field: "spec.replicas", live: 2 },
        ],
        outcome: "DRIFTED",
      },
      "2026-07-31T00:00:05.000Z",
    );

    expect(repository.get("scan-injection")).toMatchObject({
      differences: [{ desired: 1, field: "spec.replicas", live: 2 }],
      durable: true,
      outcome: "DRIFTED",
      requestedRef,
      stages: [
        { at: "2026-07-31T00:00:00.000Z", stage: "QUEUED" },
        { at: "2026-07-31T00:00:01.000Z", stage: "LOADING_DESIRED" },
        { at: "2026-07-31T00:00:02.000Z", stage: "READING_LIVE" },
        { at: "2026-07-31T00:00:03.000Z", stage: "COMPARING" },
        { at: "2026-07-31T00:00:04.000Z", stage: "SAVING_RESULT" },
        { at: "2026-07-31T00:00:05.000Z", stage: "COMPLETED" },
      ],
      status: "COMPLETED",
    });
    repository.close();
  });

  it("returns bounded newest-first history in one query contract", () => {
    const repository = new SqliteScanRepository(":memory:");
    repository.createQueued("old", "main", "2026-07-31T00:00:00.000Z");
    repository.createQueued("middle", "main", "2026-07-31T00:00:01.000Z");
    repository.createQueued("new", "main", "2026-07-31T00:00:02.000Z");

    expect(repository.list(2).map(({ id }) => id)).toEqual(["new", "middle"]);
    repository.close();
  });

  it("persists safe terminal failures without upstream detail", () => {
    const repository = new SqliteScanRepository(":memory:");
    repository.createQueued("failed", "main", "2026-07-31T00:00:00.000Z");
    repository.fail(
      "failed",
      { code: "GITHUB_UNAVAILABLE", message: "GitHub is unavailable." },
      "2026-07-31T00:00:01.000Z",
    );

    expect(repository.get("failed")).toMatchObject({
      error: {
        code: "GITHUB_UNAVAILABLE",
        message: "GitHub is unavailable.",
      },
      stage: "FAILED",
      status: "FAILED",
    });
    repository.close();
  });
});

import { describe, expect, it, vi } from "vitest";

import { ScanExecutionError } from "@/server/scans/errors";
import type { DesiredStateReader } from "@/server/scans/github";
import type { LiveDeploymentReader } from "@/server/scans/kubernetes";
import {
  SqliteScanRepository,
  type ScanRepository,
} from "@/server/scans/repository";
import { ScanService } from "@/server/scans/service";

const SHA = "0123456789abcdef0123456789abcdef01234567";
const SOURCE = { manifestPath: "deployment.yaml", repository: "owner/repo" };
const MANIFEST = `apiVersion: apps/v1
kind: Deployment
metadata:
  name: app
  namespace: demo
spec:
  replicas: 2
  template:
    spec:
      containers:
        - name: api
          image: api:1
`;

function clock(): () => string {
  let seconds = 0;
  return () =>
    `2026-07-31T00:00:${String(seconds++).padStart(2, "0")}.000Z`;
}

function service(
  repository: ScanRepository,
  desiredState: DesiredStateReader,
  liveState: LiveDeploymentReader,
): ScanService {
  return new ScanService(
    repository,
    desiredState,
    liveState,
    SOURCE,
    clock(),
    () => "scan-1",
  );
}

describe("ScanService", () => {
  it("drives every stage to persisted deterministic completion", async () => {
    const repository = new SqliteScanRepository(":memory:");
    const desiredState = {
      load: vi.fn().mockResolvedValue({ resolvedSha: SHA, yaml: MANIFEST }),
    };
    const liveState = {
      read: vi.fn().mockResolvedValue({
        containers: [{ image: "api:1", name: "api" }],
        replicas: 2,
      }),
    };
    const scans = service(repository, desiredState, liveState);

    expect(scans.start("main")).toMatchObject({
      requestedRef: "main",
      status: "QUEUED",
    });
    await scans.run("scan-1");

    expect(scans.get("scan-1")).toMatchObject({
      differences: [],
      durable: true,
      outcome: "IN_SYNC",
      resolvedSha: SHA,
      stages: [
        { stage: "QUEUED" },
        { stage: "LOADING_DESIRED" },
        { stage: "READING_LIVE" },
        { stage: "COMPARING" },
        { stage: "SAVING_RESULT" },
        { stage: "COMPLETED" },
      ],
      status: "COMPLETED",
      target: { name: "app", namespace: "demo" },
    });
    expect(desiredState.load).toHaveBeenCalledOnce();
    expect(liveState.read).toHaveBeenCalledOnce();
    repository.close();
  });

  it("completes a Kubernetes 404 projection as MISSING_LIVE", async () => {
    const repository = new SqliteScanRepository(":memory:");
    const scans = service(
      repository,
      { load: vi.fn().mockResolvedValue({ resolvedSha: SHA, yaml: MANIFEST }) },
      { read: vi.fn().mockResolvedValue(null) },
    );

    scans.start("main");
    await scans.run("scan-1");

    expect(scans.get("scan-1")).toMatchObject({
      error: null,
      outcome: "MISSING_LIVE",
      status: "COMPLETED",
    });
    repository.close();
  });

  it.each([
    [
      "GitHub failure",
      new ScanExecutionError("GITHUB_UNAVAILABLE"),
      MANIFEST,
      null,
      "GITHUB_UNAVAILABLE",
    ],
    [
      "invalid manifest",
      null,
      "not: [valid",
      null,
      "MANIFEST_INVALID",
    ],
    [
      "Kubernetes denial",
      null,
      MANIFEST,
      new ScanExecutionError("KUBERNETES_FORBIDDEN"),
      "KUBERNETES_FORBIDDEN",
    ],
  ])(
    "persists one safe terminal %s without automatic retry",
    async (_name, desiredError, yaml, liveError, code) => {
      const repository = new SqliteScanRepository(":memory:");
      const desiredState = {
        load: desiredError
          ? vi.fn().mockRejectedValue(desiredError)
          : vi.fn().mockResolvedValue({ resolvedSha: SHA, yaml }),
      };
      const liveState = {
        read: liveError
          ? vi.fn().mockRejectedValue(liveError)
          : vi.fn().mockResolvedValue({
              containers: [{ image: "api:1", name: "api" }],
              replicas: 2,
            }),
      };
      const scans = service(repository, desiredState, liveState);

      scans.start("main");
      await scans.run("scan-1");

      expect(scans.get("scan-1")).toMatchObject({
        error: { code },
        stage: "FAILED",
        status: "FAILED",
      });
      expect(desiredState.load).toHaveBeenCalledOnce();
      expect(liveState.read).toHaveBeenCalledTimes(
        desiredError || yaml !== MANIFEST ? 0 : 1,
      );
      repository.close();
    },
  );

  it("rejects a concurrent start without creating another scan", () => {
    const repository = new SqliteScanRepository(":memory:");
    const scans = service(
      repository,
      { load: vi.fn() },
      { read: vi.fn() },
    );
    scans.start("main");

    expect(() => scans.start("other")).toThrowError(
      expect.objectContaining<Partial<ScanExecutionError>>({
        code: "SCAN_ACTIVE",
      }),
    );
    expect(repository.list(10)).toHaveLength(1);
    repository.close();
  });

  it("releases admission when the initial scan write fails and creates no scan", () => {
    const durable = new SqliteScanRepository(":memory:");
    let attempts = 0;
    const repository = new Proxy(durable, {
      get(target, property, receiver) {
        if (property === "createQueued") {
          return (...args: Parameters<ScanRepository["createQueued"]>) => {
            attempts += 1;
            if (attempts === 1) {
              throw new ScanExecutionError("STORAGE_WRITE_FAILED");
            }
            return target.createQueued(...args);
          };
        }
        return Reflect.get(target, property, receiver);
      },
    }) as ScanRepository;
    const scans = service(
      repository,
      { load: vi.fn() },
      { read: vi.fn() },
    );

    expect(() => scans.start("first")).toThrow();
    expect(durable.list(10)).toEqual([]);
    expect(scans.start("second")).toMatchObject({ requestedRef: "second" });
    durable.close();
  });

  it("exposes a later storage failure as volatile without false durable history", async () => {
    const durable = new SqliteScanRepository(":memory:");
    const repository: ScanRepository = {
      complete: () => {
        throw new ScanExecutionError("STORAGE_WRITE_FAILED");
      },
      createQueued: (...args) => durable.createQueued(...args),
      fail: () => {
        throw new ScanExecutionError("STORAGE_WRITE_FAILED");
      },
      get: (...args) => durable.get(...args),
      list: (...args) => durable.list(...args),
      saveDesired: () => {
        throw new ScanExecutionError("STORAGE_WRITE_FAILED");
      },
      saveLive: () => {
        throw new ScanExecutionError("STORAGE_WRITE_FAILED");
      },
      transition: () => {
        throw new ScanExecutionError("STORAGE_WRITE_FAILED");
      },
    };
    const scans = service(
      repository,
      { load: vi.fn() },
      { read: vi.fn() },
    );

    scans.start("main");
    await scans.run("scan-1");

    expect(scans.get("scan-1")).toMatchObject({
      durable: false,
      error: { code: "STORAGE_WRITE_FAILED" },
      stage: "FAILED",
      status: "FAILED",
    });
    expect(durable.get("scan-1")).toMatchObject({
      durable: true,
      error: null,
      stage: "QUEUED",
      status: "QUEUED",
    });
    durable.close();
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";

import {
  getScanResponse,
  listScansResponse,
  sourceResponse,
  startScanResponse,
} from "@/server/scans/api";
import { ScanExecutionError } from "@/server/scans/errors";
import { SqliteScanRepository } from "@/server/scans/repository";
import { ScanService } from "@/server/scans/service";

const repositories: SqliteScanRepository[] = [];
const SHA = "0123456789abcdef0123456789abcdef01234567";
const MANIFEST = `apiVersion: apps/v1
kind: Deployment
metadata:
  name: app
  namespace: demo
spec:
  template:
    spec:
      containers:
        - name: api
          image: api:1
`;

function createService(): ScanService {
  const repository = new SqliteScanRepository(":memory:");
  repositories.push(repository);
  let id = 0;
  return new ScanService(
    repository,
    {
      load: vi.fn().mockResolvedValue({ resolvedSha: SHA, yaml: MANIFEST }),
    },
    {
      read: vi.fn().mockResolvedValue({
        containers: [{ image: "api:1", name: "api" }],
        replicas: 1,
      }),
    },
    { manifestPath: "deployment.yaml", repository: "owner/repo" },
    () => "2026-07-31T00:00:00.000Z",
    () => `scan-${++id}`,
  );
}

function post(body: string): Request {
  return new Request("http://localhost/api/scans", {
    body,
    headers: { "content-type": "application/json" },
    method: "POST",
  });
}

afterEach(() => {
  for (const repository of repositories.splice(0)) {
    repository.close();
  }
});

describe("scan API contracts", () => {
  it("validates input before creating work", async () => {
    const service = createService();
    for (const body of ["{}", '{"ref":"bad ref"}', "not-json"]) {
      const response = await startScanResponse(body === "not-json" ? post(body) : post(body), service, vi.fn());
      expect(response.status).toBe(400);
      await expect(response.json()).resolves.toEqual({
        error: { code: "INVALID_REQUEST", message: "Request is invalid." },
      });
    }
  });

  it("returns 202 immediately, then polling observes persisted completion", async () => {
    const service = createService();
    const tasks: Array<() => Promise<void>> = [];
    const response = await startScanResponse(
      post('{"ref":"main"}'),
      service,
      (task) => tasks.push(task),
    );

    expect(response.status).toBe(202);
    const queued = (await response.json()) as { scan: { id: string } };
    expect(queued.scan).toMatchObject({ id: "scan-1", status: "QUEUED" });
    expect(tasks).toHaveLength(1);

    await tasks[0]!();
    const detail = getScanResponse("scan-1", service);
    expect(detail.status).toBe(200);
    await expect(detail.json()).resolves.toMatchObject({
      scan: {
        outcome: "IN_SYNC",
        resolvedSha: SHA,
        status: "COMPLETED",
      },
    });
  });

  it("returns active conflict without scheduling a second workflow", async () => {
    const service = createService();
    const schedule = vi.fn();
    expect(
      (await startScanResponse(post('{"ref":"main"}'), service, schedule))
        .status,
    ).toBe(202);

    const conflict = await startScanResponse(
      post('{"ref":"other"}'),
      service,
      schedule,
    );
    expect(conflict.status).toBe(409);
    await expect(conflict.json()).resolves.toEqual({
      error: {
        code: "SCAN_ACTIVE",
        message: "Another scan is active.",
      },
    });
    expect(schedule).toHaveBeenCalledOnce();
  });

  it("returns bounded history, source metadata, invalid limit, and not-found", async () => {
    const service = createService();
    service.start("main");

    const history = listScansResponse(
      new Request("http://localhost/api/scans?limit=1"),
      service,
    );
    expect(history.status).toBe(200);
    await expect(history.json()).resolves.toMatchObject({
      scans: [{ id: "scan-1" }],
    });

    const badLimit = listScansResponse(
      new Request("http://localhost/api/scans?limit=51"),
      service,
    );
    expect(badLimit.status).toBe(400);

    const missing = getScanResponse("missing", service);
    expect(missing.status).toBe(404);
    await expect(missing.json()).resolves.toEqual({
      error: { code: "SCAN_NOT_FOUND", message: "Scan was not found." },
    });

    await expect(sourceResponse(service).json()).resolves.toEqual({
      source: {
        manifestPath: "deployment.yaml",
        repository: "owner/repo",
      },
    });
  });

  it("maps synchronous initial storage failure to a safe 503", async () => {
    const service = createService();
    vi.spyOn(service, "start").mockImplementation(() => {
      throw new ScanExecutionError("STORAGE_WRITE_FAILED");
    });

    const response = await startScanResponse(
      post('{"ref":"main"}'),
      service,
      vi.fn(),
    );
    expect(response.status).toBe(503);
    await expect(response.json()).resolves.toEqual({
      error: {
        code: "STORAGE_WRITE_FAILED",
        message: "Scan progress could not be saved.",
      },
    });
  });
});

