    85	              name: string;
    86	            } =>
    87	              typeof container.name === "string" &&
    88	              typeof container.image === "string",
    89	          )
    90	          .map(({ image, name }) => ({ image, name }))
    91	          .sort((left, right) => left.name.localeCompare(right.name)),
    92	        replicas: deployment.spec?.replicas ?? 1,
    93	      };
    94	    } catch (error) {
    95	      if (error instanceof ScanExecutionError) {
    96	        throw error;
    97	      }
    98	      if (controller.signal.aborted) {
    99	        throw new ScanExecutionError("KUBERNETES_TIMEOUT", { cause: error });
   100	      }
   101	      if (error instanceof ApiException) {
   102	        if (error.code === 404) {
   103	          return null;
   104	        }
   105	        if (error.code === 401 || error.code === 403) {
   106	          throw new ScanExecutionError("KUBERNETES_FORBIDDEN", {
   107	            cause: error,
   108	          });
   109	        }
   110	      }
   111	      throw new ScanExecutionError("KUBERNETES_UNAVAILABLE", { cause: error });
   112	    } finally {
   113	      clearTimeout(timeout);
   114	    }
   115	  }
   116	}

