 37	interface ScanRow extends Record<string, unknown> {
 38	  completed_at: string | null;
 39	  created_at: string;
 40	  desired_json: string | null;
 41	  differences_json: string | null;
 42	  error_code: SafeScanError["code"] | null;
 43	  error_message: string | null;
 44	  id: string;
 45	  live_json: string | null;
 46	  outcome: ScanRecord["outcome"];
 47	  requested_ref: string;
 48	  resolved_sha: string | null;
 49	  stage: ScanStage;
 50	  status: ScanStatus;
 51	  target_api_version: "apps/v1" | null;
 52	  target_kind: "Deployment" | null;
 53	  target_name: string | null;
