 62	
 63	const SCAN_COLUMNS = `
 64	  s.id, s.requested_ref, s.resolved_sha,
 65	  s.target_api_version, s.target_kind, s.target_namespace, s.target_name,
 66	  s.status, s.stage, s.outcome, s.desired_json, s.live_json,
 67	  s.differences_json, s.error_code, s.error_message,
 68	  s.created_at, s.updated_at, s.completed_at
 69	`;
 70	
 71	const SCHEMA = `
 72	  CREATE TABLE scans (
 73	    id TEXT PRIMARY KEY,
 74	    requested_ref TEXT NOT NULL,
 75	    resolved_sha TEXT,
 76	    target_api_version TEXT,
 77	    target_kind TEXT,
 78	    target_namespace TEXT,
 79	    target_name TEXT,
 80	    status TEXT NOT NULL,
 81	    stage TEXT NOT NULL,
 82	    outcome TEXT,
 83	    desired_json TEXT,
 84	    live_json TEXT,
 85	    differences_json TEXT,
 86	    error_code TEXT,
 87	    error_message TEXT,
 88	    created_at TEXT NOT NULL,
 89	    updated_at TEXT NOT NULL,
 90	    completed_at TEXT
 91	  ) STRICT;
 92	  CREATE TABLE scan_stages (
 93	    scan_id TEXT NOT NULL REFERENCES scans(id),
 94	    position INTEGER NOT NULL,
 95	    stage TEXT NOT NULL,
 96	    at TEXT NOT NULL,
 97	    PRIMARY KEY (scan_id, position)
 98	  ) STRICT;
 99	  CREATE INDEX scans_created_at_idx ON scans(created_at DESC);
100	`;
101	
102	function parseJson<T>(value: string | null, fallback: T): T {
103	  if (value === null) {
104	    return fallback;
105	  }
106	
107	  try {
108	    return JSON.parse(value) as T;
109	  } catch (error) {
110	    throw new ScanExecutionError("STORAGE_UNAVAILABLE", { cause: error });
111	  }
112	}
113	
114	function recordFromRows(row: ScanRow, stages: StageRecord[]): ScanRecord {
115	  const target =
116	    row.target_api_version &&
117	    row.target_kind &&
118	    row.target_namespace &&
119	    row.target_name
120	      ? {
121	          apiVersion: row.target_api_version,
122	          kind: row.target_kind,
123	          name: row.target_name,
124	          namespace: row.target_namespace,
125	        }
126	      : null;
127	  const error =
128	    row.error_code && row.error_message
129	      ? { code: row.error_code, message: row.error_message }
130	      : null;
131	
132	  return {
133	    completedAt: row.completed_at,
134	    createdAt: row.created_at,
135	    desired: parseJson(row.desired_json, null),
136	    differences: parseJson(row.differences_json, []),
137	    durable: true,
138	    error,
139	    id: row.id,
140	    live: parseJson(row.live_json, null),
141	    outcome: row.outcome,
142	    requestedRef: row.requested_ref,
143	    resolvedSha: row.resolved_sha,
144	    stage: row.stage,
145	    stages,
146	    status: row.status,
147	    target,
148	    updatedAt: row.updated_at,
149	  };
150	}
