152	export class SqliteScanRepository implements ScanRepository {
153	  private readonly database: DatabaseSync;
154	
155	  constructor(path: string) {
156	    try {
157	      this.database = new DatabaseSync(path);
158	      this.bootstrap();
159	    } catch (error) {
160	      throw new ScanExecutionError("STORAGE_UNAVAILABLE", { cause: error });
161	    }
162	  }
163	
164	  close(): void {
165	    this.database.close();
166	  }
167	
168	  createQueued(id: string, requestedRef: string, at: string): ScanRecord {
169	    this.write(() => {
170	      this.database
171	        .prepare(
172	          `INSERT INTO scans (
173	            id, requested_ref, status, stage, created_at, updated_at
174	          ) VALUES (?, ?, 'QUEUED', 'QUEUED', ?, ?)`,
175	        )
176	        .run(id, requestedRef, at, at);
177	      this.appendStage(id, "QUEUED", at);
178	    });
179	
180	    const record = this.get(id);
181	    if (!record) {
182	      throw new ScanExecutionError("STORAGE_WRITE_FAILED");
183	    }
184	    return record;
185	  }
186	
187	  transition(
188	    id: string,
189	    stage: ScanStage,
190	    status: ScanStatus,
191	    at: string,
192	  ): void {
193	    this.write(() => {
194	      this.requireChange(
195	        this.database
196	          .prepare(
197	            "UPDATE scans SET stage = ?, status = ?, updated_at = ? WHERE id = ?",
198	          )
199	          .run(stage, status, at, id).changes,
200	      );
201	      this.appendStage(id, stage, at);
202	    });
203	  }
204	
205	  saveDesired(
206	    id: string,
207	    resolvedSha: string,
208	    target: DeploymentTarget,
209	    desired: DeploymentProjection,
210	    at: string,
211	  ): void {
212	    this.write(() => {
213	      this.requireChange(
214	        this.database
215	          .prepare(
216	            `UPDATE scans SET
217	              resolved_sha = ?, target_api_version = ?, target_kind = ?,
218	              target_namespace = ?, target_name = ?, desired_json = ?,
219	              stage = 'READING_LIVE', status = 'RUNNING', updated_at = ?
220	            WHERE id = ?`,
221	          )
222	          .run(
223	            resolvedSha,
224	            target.apiVersion,
225	            target.kind,
226	            target.namespace,
227	            target.name,
228	            JSON.stringify(desired),
229	            at,
230	            id,
231	          ).changes,
232	      );
233	      this.appendStage(id, "READING_LIVE", at);
234	    });
235	  }
236	
237	  saveLive(id: string, live: DeploymentProjection | null, at: string): void {
238	    this.write(() => {
239	      this.requireChange(
240	        this.database
241	          .prepare(
242	            `UPDATE scans SET
243	              live_json = ?, stage = 'COMPARING', updated_at = ?
244	            WHERE id = ?`,
245	          )
246	          .run(live === null ? null : JSON.stringify(live), at, id).changes,
247	      );
248	      this.appendStage(id, "COMPARING", at);
249	    });
250	  }
251	
252	  complete(id: string, result: ComparisonResult, at: string): void {
253	    this.write(() => {
254	      this.requireChange(
255	        this.database
256	          .prepare(
257	            `UPDATE scans SET
258	              outcome = ?, differences_json = ?, status = 'COMPLETED',
259	              stage = 'COMPLETED', updated_at = ?, completed_at = ?
260	            WHERE id = ?`,
261	          )
262	          .run(result.outcome, JSON.stringify(result.differences), at, at, id)
263	          .changes,
264	      );
265	      this.appendStage(id, "COMPLETED", at);
266	    });
267	  }
268	
269	  fail(id: string, error: SafeScanError, at: string): void {
270	    this.write(() => {
271	      this.requireChange(
272	        this.database
273	          .prepare(
274	            `UPDATE scans SET
275	              error_code = ?, error_message = ?, status = 'FAILED',
276	              stage = 'FAILED', updated_at = ?, completed_at = ?
277	            WHERE id = ?`,
278	          )
279	          .run(error.code, error.message, at, at, id).changes,
280	      );
281	      this.appendStage(id, "FAILED", at);
282	    });
283	  }
284	
285	  get(id: string): ScanRecord | null {
286	    try {
287	      const rows = this.database
288	        .prepare(
289	          `SELECT ${SCAN_COLUMNS},
290	            st.stage AS stage_name, st.at AS stage_at
291	          FROM scans s
292	          LEFT JOIN scan_stages st ON st.scan_id = s.id
293	          WHERE s.id = ?
294	          ORDER BY st.position ASC`,
295	        )
296	        .all(id) as JoinedScanRow[];
297	      if (rows.length === 0) {
298	        return null;
299	      }
300	      return recordFromRows(rows[0]!, this.stageRows(rows));
301	    } catch (error) {
302	      throw new ScanExecutionError("STORAGE_UNAVAILABLE", { cause: error });
303	    }
304	  }
305	
306	  list(limit: number): ScanRecord[] {
307	    try {
308	      const rows = this.database
309	        .prepare(
310	          `SELECT ${SCAN_COLUMNS},
311	            st.stage AS stage_name, st.at AS stage_at
312	          FROM (
313	            SELECT * FROM scans ORDER BY created_at DESC, id DESC LIMIT ?
314	          ) s
315	          LEFT JOIN scan_stages st ON st.scan_id = s.id
316	          ORDER BY s.created_at DESC, s.id DESC, st.position ASC`,
317	        )
318	        .all(limit) as JoinedScanRow[];
319	      const records = new Map<
320	        string,
321	        { row: ScanRow; stages: StageRecord[] }
322	      >();
323	      for (const row of rows) {
324	        const entry = records.get(row.id) ?? { row, stages: [] };
325	        if (row.stage_name && row.stage_at) {
326	          entry.stages.push({ at: row.stage_at, stage: row.stage_name });
327	        }
328	        records.set(row.id, entry);
329	      }
330	      return [...records.values()].map(({ row, stages }) =>
331	        recordFromRows(row, stages),
332	      );
333	    } catch (error) {
334	      throw new ScanExecutionError("STORAGE_UNAVAILABLE", { cause: error });
335	    }
336	  }
337	
338	  private bootstrap(): void {
339	    this.database.exec("PRAGMA foreign_keys = ON");
340	    const row = this.database.prepare("PRAGMA user_version").get() as {
341	      user_version: number;
342	    };
343	    if (row.user_version === 1) {
344	      return;
345	    }
346	    if (row.user_version !== 0) {
347	      throw new Error(
348	        `Unsupported database schema version: ${row.user_version}`,
349	      );
350	    }
351	
352	    this.write(() => {
353	      this.database.exec(SCHEMA);
354	      this.database.exec("PRAGMA user_version = 1");
355	    });
356	  }
357	
358	  private appendStage(id: string, stage: ScanStage, at: string): void {
359	    this.database
360	      .prepare(
361	        `INSERT INTO scan_stages (scan_id, position, stage, at)
362	         VALUES (
363	           ?,
364	           COALESCE(
365	             (SELECT MAX(position) + 1 FROM scan_stages WHERE scan_id = ?),
366	             0
367	           ),
368	           ?,
369	           ?
370	         )`,
371	      )
372	      .run(id, id, stage, at);
373	  }
374	
375	  private requireChange(changes: number | bigint): void {
376	    if (changes !== 1 && changes !== 1n) {
377	      throw new Error("Scan record was not updated.");
378	    }
379	  }
380	
381	  private stageRows(rows: JoinedScanRow[]): StageRecord[] {
382	    return rows.flatMap((row) =>
383	      row.stage_name && row.stage_at
384	        ? [{ at: row.stage_at, stage: row.stage_name }]
385	        : [],
386	    );
387	  }
388	
389	  private write(operation: () => void): void {
390	    try {
391	      this.database.exec("BEGIN IMMEDIATE");
392	      operation();
393	      this.database.exec("COMMIT");
394	    } catch (error) {
395	      try {
396	        this.database.exec("ROLLBACK");
397	      } catch {
398	        // Preserve the original storage failure.
399	      }
400	      if (error instanceof ScanExecutionError) {
401	        throw error;
402	      }
403	      throw new ScanExecutionError("STORAGE_WRITE_FAILED", { cause: error });
404	    }
405	  }
406	}
