 12	
 13	export type Clock = () => string;
 14	export type IdFactory = () => string;
 15	
 16	export class ScanService {
 17	  private activeScanId: string | null = null;
 18	  private readonly volatileFailures = new Map<string, ScanRecord>();
 19	
 20	  constructor(
 21	    private readonly repository: ScanRepository,
 22	    private readonly desiredState: DesiredStateReader,
 23	    private readonly liveState: LiveDeploymentReader,
 24	    private readonly sourceMetadata: SourceMetadata,
 25	    private readonly clock: Clock = () => new Date().toISOString(),
 26	    private readonly idFactory: IdFactory = randomUUID,
 27	  ) {}
 28	
 29	  source(): SourceMetadata {
 30	    return this.sourceMetadata;
 31	  }
 32	
 33	  start(requestedRef: string): ScanRecord {
 34	    if (this.activeScanId !== null) {
 35	      throw new ScanExecutionError("SCAN_ACTIVE");
 36	    }
 37	
 38	    const id = this.idFactory();
 39	    this.activeScanId = id;
 40	    try {
 41	      return this.repository.createQueued(id, requestedRef, this.clock());
 42	    } catch (error) {
 43	      this.activeScanId = null;
 44	      throw error;
 45	    }
 46	  }
 47	
 48	  async run(id: string): Promise<void> {
 49	    if (this.activeScanId !== id) {
 50	      return;
 51	    }
 52	
 53	    try {
 54	      this.repository.transition(
 55	        id,
 56	        "LOADING_DESIRED",
 57	        "RUNNING",
 58	        this.clock(),
 59	      );
 60	      const queued = this.repository.get(id);
 61	      if (!queued) {
 62	        throw new ScanExecutionError("SCAN_NOT_FOUND");
 63	      }
 64	
 65	      const desiredSource = await this.desiredState.load(queued.requestedRef);
 66	      const desired = parseDesiredDeployment(desiredSource.yaml);
 67	      this.repository.saveDesired(
 68	        id,
 69	        desiredSource.resolvedSha,
 70	        desired.target,
 71	        desired.projection,
 72	        this.clock(),
 73	      );
 74	
 75	      const live = await this.liveState.read(desired.target);
 76	      this.repository.saveLive(id, live, this.clock());
 77	      const result = compareDeployments(desired.projection, live);
 78	
 79	      this.repository.transition(id, "SAVING_RESULT", "RUNNING", this.clock());
 80	      this.repository.complete(id, result, this.clock());
 81	    } catch (error) {
 82	      const safeError = safeScanError(error);
 83	      try {
 84	        this.repository.fail(id, safeError, this.clock());
 85	      } catch {
 86	        this.recordVolatileStorageFailure(id);
 87	      }
 88	    } finally {
 89	      this.activeScanId = null;
 90	    }
 91	  }
 92	
 93	  get(id: string): ScanRecord | null {
 94	    return this.volatileFailures.get(id) ?? this.repository.get(id);
 95	  }
 96	
 97	  list(limit: number): ScanRecord[] {
 98	    const durable = this.repository.list(limit);
 99	    return durable.map(
100	      (record) => this.volatileFailures.get(record.id) ?? record,
101	    );
102	  }
103	
104	  private recordVolatileStorageFailure(id: string): void {
105	    let record: ScanRecord | null = null;
106	    try {
107	      record = this.repository.get(id);
108	    } catch {
109	      // The API will surface repository unavailability if reads also fail.
110	    }
111	    if (!record) {
112	      return;
113	    }
114	
115	    const at = this.clock();
116	    this.volatileFailures.set(id, {
117	      ...record,
118	      completedAt: at,
119	      durable: false,
120	      error: new ScanExecutionError("STORAGE_WRITE_FAILED").toSafeError(),
121	      stage: "FAILED",
122	      status: "FAILED",
123	      updatedAt: at,
124	    });
125	    if (this.volatileFailures.size > 50) {
126	      const oldest = this.volatileFailures.keys().next().value as
127	        string | undefined;
128	      if (oldest) {
129	        this.volatileFailures.delete(oldest);
130	      }
131	    }
132	  }
133	}
