  8	function json(body: unknown, status = 200): Response {
  9	  return Response.json(body, { status });
 10	}
 11	
 12	function errorResponse(error: unknown): Response {
 13	  if (!(error instanceof ScanExecutionError)) {
 14	    return json(
 15	      { error: new ScanExecutionError("INTERNAL_ERROR").toSafeError() },
 16	      500,
 17	    );
 18	  }
 19	
 20	  const status =
 21	    error.code === "SCAN_ACTIVE"
 22	      ? 409
 23	      : error.code === "SCAN_NOT_FOUND"
 24	        ? 404
 25	        : error.code.startsWith("STORAGE_")
 26	          ? 503
 27	          : error.code === "CONFIGURATION_INVALID"
 28	            ? 503
 29	            : 500;
 30	  return json({ error: error.toSafeError() }, status);
 31	}
