 37	export async function startScanResponse(
 38	  request: Request,
 39	  service: ScanService,
 40	  schedule: Scheduler,
 41	): Promise<Response> {
 42	  try {
 43	    const text = await request.text();
 44	    if (text.length > 1_024) {
 45	      return json(
 46	        { error: { code: "INVALID_REQUEST", message: "Request is invalid." } },
 47	        400,
 48	      );
 49	    }
 50	    const parsed = startScanSchema.safeParse(JSON.parse(text));
 51	    if (!parsed.success) {
 52	      return json(
 53	        { error: { code: "INVALID_REQUEST", message: "Request is invalid." } },
 54	        400,
 55	      );
 56	    }
 57	
 58	    const scan = service.start(parsed.data.ref);
 59	    schedule(() => service.run(scan.id));
 60	    return json(scanEnvelope(scan), 202);
 61	  } catch (error) {
 62	    if (error instanceof SyntaxError) {
 63	      return json(
 64	        { error: { code: "INVALID_REQUEST", message: "Request is invalid." } },
 65	        400,
 66	      );
 67	    }
 68	    return errorResponse(error);
 69	  }
 70	}
