  2	
  3	const FULL_SHA = /^[0-9a-f]{40}$/;
  4	const GITHUB_REPOSITORY =
  5	  /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})\/[A-Za-z0-9._-]{1,100}$/;
  6	
  7	type ConfiguredRuntimeMode = "development" | "test" | "production";
  8	
  9	export type RuntimeMode = ConfiguredRuntimeMode | "invalid";
 10	
 11	export type ConfigurationIssue =
 12	  | "RUNTIME_MODE_INVALID"
 13	  | "BUILD_SHA_REQUIRED"
 14	  | "BUILD_SHA_INVALID"
 15	  | "DATA_DIR_INVALID"
 16	  | "GITHUB_REPOSITORY_INVALID"
 17	  | "GITHUB_REPOSITORY_REQUIRED"
 18	  | "KUBECONFIG_PATH_INVALID"
 19	  | "KUBECONFIG_PATH_REQUIRED"
 20	  | "KUBECONTEXT_INVALID"
 21	  | "MANIFEST_PATH_INVALID"
 22	  | "MANIFEST_PATH_REQUIRED";
 23	
 24	export interface RuntimeEnvironment {
 25	  DRIFTLENS_BUILD_SHA?: string;
 26	  DRIFTLENS_DATA_DIR?: string;
 27	  DRIFTLENS_GITHUB_REPOSITORY?: string;
 28	  DRIFTLENS_KUBECONFIG_PATH?: string;
 29	  DRIFTLENS_KUBECONTEXT?: string;
 30	  DRIFTLENS_MANIFEST_PATH?: string;
 31	  NODE_ENV?: string;
 32	}
 33	
 34	export interface RuntimeConfiguration {
 35	  buildSha: string;
 36	  dataDirectory: string;
 37	  issues: ConfigurationIssue[];
 38	  mode: RuntimeMode;
 39	  ready: boolean;
 40	  scan: {
 41	    kubeconfigPath: string;
 42	    kubeContext?: string;
 43	    manifestPath: string;
 44	    repository: string;
 45	  };
 46	}
 47	
 48	export function readRuntimeEnvironment(): RuntimeEnvironment {
 49	  const readValue = (name: keyof RuntimeEnvironment): string | undefined => {
 50	    const value: unknown = Reflect.get(process.env, name);
 51	    return typeof value === "string" ? value : undefined;
 52	  };
 53	
 54	  return {
 55	    DRIFTLENS_BUILD_SHA: readValue("DRIFTLENS_BUILD_SHA"),
 56	    DRIFTLENS_DATA_DIR: readValue("DRIFTLENS_DATA_DIR"),
 57	    DRIFTLENS_GITHUB_REPOSITORY: readValue("DRIFTLENS_GITHUB_REPOSITORY"),
 58	    DRIFTLENS_KUBECONFIG_PATH: readValue("DRIFTLENS_KUBECONFIG_PATH"),
 59	    DRIFTLENS_KUBECONTEXT: readValue("DRIFTLENS_KUBECONTEXT"),
 60	    DRIFTLENS_MANIFEST_PATH: readValue("DRIFTLENS_MANIFEST_PATH"),
 61	    NODE_ENV: readValue("NODE_ENV"),
 62	  };
 63	}
 64	
 65	function runtimeMode(
 66	  value: string | undefined,
 67	  issues: ConfigurationIssue[],
 68	): RuntimeMode {
 69	  if (value === "development" || value === "production" || value === "test") {
 70	    return value;
 71	  }
 72	
 73	  issues.push("RUNTIME_MODE_INVALID");
 74	  return "invalid";
 75	}
 76	
 77	function resolveBuildSha(
 78	  value: string | undefined,
 79	  mode: RuntimeMode,
 80	  issues: ConfigurationIssue[],
 81	): string {
 82	  const buildSha = value?.trim();
 83	
 84	  if (!buildSha) {
 85	    if (mode === "production") {
 86	      issues.push("BUILD_SHA_REQUIRED");
 87	      return "unavailable";
 88	    }
 89	
 90	    return mode === "invalid" ? "unavailable" : "development";
 91	  }
 92	
 93	  if (!FULL_SHA.test(buildSha)) {
 94	    issues.push("BUILD_SHA_INVALID");
 95	    return "unavailable";
 96	  }
 97	
 98	  return buildSha;
 99	}
100	
101	function resolveDataDirectory(
102	  value: string | undefined,
103	  mode: RuntimeMode,
104	  issues: ConfigurationIssue[],
105	): string {
106	  if (mode === "invalid") {
107	    return "unavailable";
108	  }
109	
110	  const dataDirectory =
111	    value?.trim() || (mode === "production" ? "/data" : ".driftlens");
112	
113	  if (dataDirectory.includes("\0")) {
114	    issues.push("DATA_DIR_INVALID");
115	    return "unavailable";
116	  }
117	
118	  if (mode === "production" && !dataDirectory.startsWith("/")) {
119	    issues.push("DATA_DIR_INVALID");
120	    return "unavailable";
121	  }
122	
123	  return dataDirectory;
124	}
125	
126	function requiredValue(
127	  value: string | undefined,
128	  requiredIssue: ConfigurationIssue,
129	  invalidIssue: ConfigurationIssue,
130	  isValid: (candidate: string) => boolean,
131	  issues: ConfigurationIssue[],
132	): string {
133	  const candidate = value?.trim();
134	  if (!candidate) {
135	    issues.push(requiredIssue);
136	    return "unavailable";
137	  }
138	  if (!isValid(candidate)) {
139	    issues.push(invalidIssue);
140	    return "unavailable";
141	  }
142	  return candidate;
143	}
144	
145	function safeManifestPath(value: string): boolean {
146	  return (
147	    value.length <= 500 &&
148	    !value.startsWith("/") &&
149	    !value.includes("\\") &&
150	    !value.includes("\0") &&
151	    value
152	      .split("/")
153	      .every((part) => part !== "" && part !== "." && part !== "..")
154	  );
155	}
156	
157	function optionalKubeContext(
158	  value: string | undefined,
159	  issues: ConfigurationIssue[],
160	): string | undefined {
161	  const candidate = value?.trim();
162	  if (!candidate) {
163	    return undefined;
164	  }
165	  if (
166	    candidate.length > 253 ||
167	    [...candidate].some((character) => {
168	      const code = character.charCodeAt(0);
169	      return code <= 31 || code === 127;
170	    })
171	  ) {
172	    issues.push("KUBECONTEXT_INVALID");
173	    return undefined;
174	  }
175	  return candidate;
176	}
177	
178	export function resolveRuntimeConfiguration(
179	  environment: RuntimeEnvironment = readRuntimeEnvironment(),
180	  buildShaValue: string | undefined = environment.DRIFTLENS_BUILD_SHA,
181	): RuntimeConfiguration {
182	  const issues: ConfigurationIssue[] = [];
183	  const mode = runtimeMode(environment.NODE_ENV, issues);
184	  const buildSha = resolveBuildSha(buildShaValue, mode, issues);
185	  const dataDirectory = resolveDataDirectory(
186	    environment.DRIFTLENS_DATA_DIR,
187	    mode,
188	    issues,
189	  );
190	  const repository = requiredValue(
191	    environment.DRIFTLENS_GITHUB_REPOSITORY,
192	    "GITHUB_REPOSITORY_REQUIRED",
193	    "GITHUB_REPOSITORY_INVALID",
194	    (value) => GITHUB_REPOSITORY.test(value),
195	    issues,
196	  );
197	  const manifestPath = requiredValue(
198	    environment.DRIFTLENS_MANIFEST_PATH,
199	    "MANIFEST_PATH_REQUIRED",
200	    "MANIFEST_PATH_INVALID",
201	    safeManifestPath,
202	    issues,
203	  );
204	  const kubeconfigPath = requiredValue(
205	    environment.DRIFTLENS_KUBECONFIG_PATH,
206	    "KUBECONFIG_PATH_REQUIRED",
207	    "KUBECONFIG_PATH_INVALID",
208	    (value) => isAbsolute(value) && !value.includes("\0"),
209	    issues,
210	  );
211	  const kubeContext = optionalKubeContext(
212	    environment.DRIFTLENS_KUBECONTEXT,
213	    issues,
214	  );
215	
216	  return {
217	    buildSha,
218	    dataDirectory,
219	    issues,
220	    mode,
221	    ready: issues.length === 0,
222	    scan: {
223	      kubeconfigPath,
224	      ...(kubeContext ? { kubeContext } : {}),
225	      manifestPath,
226	      repository,
227	    },
228	  };
229	}

